const schedulingReceipt={schemaVersion:1,tenantId:S,serviceId:T,timezone:offerProfile.timezone,windows:[{id:S,...schedulingInput.windows[0]}],policy:{id:U,...schedulingInput.policy}};
async function schedulingClient(responses:Response[]){const result=await offerClient([...offerContextResponses(),json({ok:true,data:offerReceipt}),...responses]);await result.c.createSimpleOffer(S,offerInput);return result;}
it('configures strict owner-created offer scheduling after fresh owner/type/timezone checks and accepts receipt key order independently',async()=>{const reordered={policy:{slotIntervalMinutes:30,horizonDays:14,leadTimeMinutes:60,id:U},windows:[{capacity:1,endMinute:1020,startMinute:540,weekday:1,id:S}],timezone:offerProfile.timezone,serviceId:T,tenantId:S,schemaVersion:1};const {c,f}=await schedulingClient([...offerContextResponses(),json({ok:true,data:reordered})]);expect(await c.createOfferScheduling(S,T,schedulingInput)).toEqual(schedulingReceipt);expect(c.offerSchedulingState(S,T)).toMatchObject({phase:'configured',receipt:schedulingReceipt});expect(f.mock.calls[11]).toEqual(['https://api.example.test/api/catalog/simple-offers/'+T+'/scheduling?tenantId='+S,{method:'POST',credentials:'omit',cache:'no-store',redirect:'error',referrerPolicy:'no-referrer',headers:{Authorization:'Bearer private-business-owner','Content-Type':'application/json'},body:JSON.stringify(schedulingInput)}]);expect(JSON.stringify(c.offerSchedulingState(S,T))).not.toContain('private-business-owner');});
it.each([{windows:[]},{windows:[{weekday:1,startMinute:540,endMinute:570,capacity:1}]},{windows:[{weekday:1,startMinute:1020,endMinute:540,capacity:1}]},{windows:[{weekday:1,startMinute:540,endMinute:1020,capacity:2}]},{windows:[{weekday:2,startMinute:540,endMinute:1020,capacity:1},{weekday:1,startMinute:540,endMinute:1020,capacity:1}]},{windows:[{weekday:1,startMinute:540,endMinute:1020,capacity:1},{weekday:1,startMinute:540,endMinute:1020,capacity:1}]},{policy:{leadTimeMinutes:10081,horizonDays:14,slotIntervalMinutes:30}},{policy:{leadTimeMinutes:60,horizonDays:31,slotIntervalMinutes:30}},{policy:{leadTimeMinutes:60,horizonDays:14,slotIntervalMinutes:5}},{tenantId:S},{serviceId:T},{price:12500},{timezone:'PST'}])('rejects invalid scheduling or authority fields before reads/writes %j',async(patch)=>{const {c,f}=await schedulingClient([]);await expect(c.createOfferScheduling(S,T,{...schedulingInput,...patch} as typeof schedulingInput)).rejects.toMatchObject({delivery:'not_sent'});expect(f).toHaveBeenCalledTimes(8);});
it('requires a known owner-created offer receipt, not an arbitrary catalog service',async()=>{const {c,f}=await businessClient([]);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'not_sent'});expect(f).toHaveBeenCalledTimes(2);const created=await schedulingClient([]);await expect(created.c.createOfferScheduling(S,U,schedulingInput)).rejects.toMatchObject({delivery:'not_sent'});expect(created.f).toHaveBeenCalledTimes(8);});
it.each([[],[{tenant_id:S,role:'BUSINESS_STAFF'}],[{tenant_id:T,role:'BUSINESS_OWNER'}],[{tenant_id:S,role:'BUSINESS_OWNER',user_id:U}]].map(rows=>[rows]))('denies scheduling without fresh exact owner %j',async(memberships)=>{const {c,f}=await schedulingClient([json(memberships)]);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toThrow();expect(c.offerSchedulingState(S,T)).toEqual({phase:'ready'});expect(f.mock.calls.some(call=>String(call[0]).includes('/scheduling?'))).toBe(false);});
it.each([{profile:{...offerProfile,timezone:'UTC'}},{profile:{...offerProfile,timezone:'America/Fake'}},{business:{...businessReceipt,businessType:'AUTO_DETAILING'}},{business:{...businessReceipt,tenantId:T}}])('denies drifted or foreign scheduling context %j',async(patch)=>{const {c,f}=await schedulingClient([json([{tenant_id:S,role:'BUSINESS_OWNER'}]),json({ok:true,data:patch.business??businessReceipt}),json({ok:true,data:{schemaVersion:1,profile:patch.profile??offerProfile}})]);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toThrow();expect(c.offerSchedulingState(S,T)).toEqual({phase:'ready'});expect(f.mock.calls.some(call=>String(call[0]).includes('/scheduling?'))).toBe(false);});
it.each([{...schedulingReceipt,serviceId:U},{...schedulingReceipt,tenantId:T},{...schedulingReceipt,schemaVersion:2},{...schedulingReceipt,extra:true},{...schedulingReceipt,windows:[{id:U,...schedulingInput.windows[0]}]},{...schedulingReceipt,windows:[{id:'invalid',...schedulingInput.windows[0]}]},{...schedulingReceipt,windows:[{...schedulingReceipt.windows[0],capacity:2}]},{...schedulingReceipt,policy:{...schedulingReceipt.policy,horizonDays:15}},{...schedulingReceipt,timezone:'UTC'}])('keeps malformed or foreign scheduling receipts unknown %j',async(receipt)=>{const {c}=await schedulingClient([...offerContextResponses(),json({ok:true,data:receipt})]);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'unknown'});expect(c.offerSchedulingState(S,T)).toMatchObject({phase:'unknown',attempt:schedulingInput});});
it('freezes unknown scheduling through conflict, read-only checks and same-actor re-sign-in without replacement writes',async()=>{const {c,f}=await schedulingClient([...offerContextResponses(),json({ok:false,code:'INTERNAL_ERROR'},500),...offerContextResponses(),json({ok:false,code:'CONFLICT'},409),json({access_token:'same-private-actor'}),json({id:U}),...offerContextResponses(),json({ok:true,data:schedulingReceipt})]);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'unknown'});const locked=c.offerSchedulingState(S,T);await expect(c.createOfferScheduling(S,T,{...schedulingInput,idempotencyKey:'replacement-schedule-0001'})).rejects.toMatchObject({delivery:'not_sent'});await expect(c.createOfferScheduling(S,T,{...schedulingInput,policy:{...schedulingInput.policy,horizonDays:15}})).rejects.toMatchObject({delivery:'not_sent'});await expect(c.publishPaidSimple(S,U,{serviceId:T,name:'form',checkoutOrigin:'https://checkout.example.test'})).rejects.toMatchObject({delivery:'not_sent'});await expect(c.setServiceActive(S,T,false)).rejects.toMatchObject({delivery:'not_sent'});await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'unknown'});expect(c.offerSchedulingState(S,T)).toEqual(locked);c.signOut();await c.signIn('owner@example.test','fixture');expect(c.offerSchedulingState(S,T)).toEqual(locked);expect(c.simpleOfferRecoveryTenant()).toBe(S);expect(c.simpleOfferState(S)).toMatchObject({phase:'created',receipt:offerReceipt});expect(await c.createOfferScheduling(S,T,schedulingInput)).toEqual(schedulingReceipt);const posts=f.mock.calls.filter(call=>String(call[0]).includes('/scheduling?'));expect(posts).toHaveLength(3);expect(posts[0]?.[1]?.body).toBe(posts[1]?.[1]?.body);expect(posts[0]?.[1]?.body).toBe(posts[2]?.[1]?.body);});
it('rejects overlapping scheduling requests and drops late receipts after auth replacement while binding replay to original actor',async()=>{const {c,f}=await schedulingClient(offerContextResponses());let finish!:(response:Response)=>void;const original=f.getMockImplementation()!;f.mockImplementation((input,init)=>String(input).includes('/scheduling?')?new Promise(resolve=>finish=resolve):original(input,init));const pending=c.createOfferScheduling(S,T,schedulingInput);await vi.waitFor(()=>expect(finish).toBeTypeOf('function'));await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'not_sent'});c.signOut();finish(json({ok:true,data:schedulingReceipt}));await expect(pending).rejects.toMatchObject({delivery:'unknown'});expect(c.offerSchedulingState(S,T)).toEqual({phase:'ready'});f.mockImplementationOnce(async()=>json({access_token:'other-private'})).mockImplementationOnce(async()=>json({id:T}));await c.signIn('other@example.test','fixture');expect(c.simpleOfferRecoveryTenant()).toBeUndefined();await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'not_sent'});});

it('uses actual scheduling HTTP and returns original rule IDs on explicit lost-receipt replay without a duplicate controlled write',async()=>{const origin='https://owner.example.test',ownerToken='private-http-scheduling';let saved:string|undefined,writes=0,lose=true;
 const server=createFlowHttpServer({repository:{call:vi.fn()},businessOnboarding:true,catalogAuthoring:true,schedulingAuthoring:true,businessProfile:async()=>BusinessProfileSchema.parse(businessReceipt),tenantProfile:async()=>({...offerProfile,status:'active'}),simpleOfferCreate:async()=>SimpleOfferReceipt.parse(offerReceipt),offerSchedulingCreate:async(actor,tenantId,serviceId,input)=>{expect([actor,tenantId,serviceId]).toEqual([U,S,T]);const body=JSON.stringify(CreateOfferScheduling.parse(input));if(saved&&saved!==body)throw new FlowError('CONFLICT');if(!saved){saved=body;writes++;}return OfferSchedulingReceipt.parse(schedulingReceipt);},ownerOrigins:[origin],customerOrigins:[],authenticateOwner:async token=>token===ownerToken?U:null});await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address();if(!address||typeof address==='string')throw Error('missing loopback');const local='http://127.0.0.1:'+address.port;
 const calls=vi.fn<typeof fetch>(async(input,init)=>{const path=String(input);if(path.includes('/token?'))return json({access_token:ownerToken});if(path.endsWith('/user'))return json({id:U});if(path.includes('/tenant_members?'))return json([{tenant_id:S,role:'BUSINESS_OWNER'}]);const response=await fetch(path.replace('https://api.example.test',local),{...init,headers:{...init?.headers,Origin:origin}});if(path.includes('/scheduling?')&&lose){lose=false;await response.text();throw Error('lost receipt');}return response;});
 try{const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},calls);await c.signIn('owner@example.test','fixture');await c.createSimpleOffer(S,offerInput);await expect(c.createOfferScheduling(S,T,schedulingInput)).rejects.toMatchObject({delivery:'unknown'});expect(writes).toBe(1);expect(await c.createOfferScheduling(S,T,schedulingInput)).toEqual(schedulingReceipt);expect(writes).toBe(1);const posts=calls.mock.calls.filter(call=>String(call[0]).includes('/scheduling?'));expect(posts).toHaveLength(2);expect(posts[0]?.[1]?.body).toBe(posts[1]?.[1]?.body);}finally{await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
});
